?>
<!doctype html><html lang="<?= htmlspecialchars($locale ?? 'cs',ENT_QUOTES,'UTF-8') ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($replace($text('title', 'ROBO {year} — Průběžné pořadí'), $year), ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="/robo/assets/app.css"></head><body class="display-page" data-endpoint="/robo/api/standings" data-refresh-ms="10000"><header><h1 class="page-title"><?= htmlspecialchars($replace($text('title', 'ROBO {year} — Průběžné pořadí'), $year), ENT_QUOTES, 'UTF-8') ?></h1></header><main><div class="data-table-wrap"><table class="data-table"><thead><tr><th><?= htmlspecialchars($text('rank', 'Pořadí'), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars($text('team', 'Tým'), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars($text('school', 'Škola'), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars($text('contestants', 'Soutěžící'), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars($text('best_time', 'Nejlepší čas'), ENT_QUOTES, 'UTF-8') ?></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td class="display-rank"><?= (int)($row['rank'] ?? 0) ?: '—' ?></td><td><?= (int)$row['number'] ?></td><td><?= htmlspecialchars((string)($row['school'] ?? ''),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars((string)($row['members'] ?? ''),ENT_QUOTES,'UTF-8') ?></td><td><?= !empty($row['total_time']) ? (int)$row['total_time'].' ms' : '—' ?></td></tr><?php endforeach; ?></tbody></table></div></main><script src="/robo/assets/app.js" defer></script></body></html>
